var r=`1242-pikliz`;var t=`world-1242`;var n=`HT`;var a=`central-america-caribbean`;var s=4;var o=203;var c={en:`Pikliz`,ua:`Пікліз`};var g={en:`Pikliz is a dish from Haiti featuring white cabbage, carrot, scotch bonnet pepper, red onion. This home-sized recipe records each ingredient at the step where it is used. This is refrigerator-vinegar pikliz, not a shelf-stable fermented or canned preserve.`,ua:`Пікліз, страва кухні країни Гаїті з такими основними складниками: білоголова капуста, морква, перець скотч-боннет, червона цибуля. У домашньому рецепті кожний продукт прив’язаний до етапу його використання. Це пікліз швидкого маринування у холодильнику, а не стабільна ферментована чи консервована заготовка.`};var l=[{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:14,i:[[`white-cabbage`,500,`g`],[`carrot`,240,`g`],[`scotch-bonnet-pepper`,1,`pcs`],[`red-onion`,170,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:7,i:[[`white-vinegar`,220,`ml`],[`lime-juice`,65,`ml`],[`table-salt`,9,`g`],[`allspice-berries`,6,`pcs`]]},{en:`Cover the vegetables completely with vinegar dressing and keep refrigerated; this quick pickled pikliz is not safe for unrefrigerated shelf storage.`,ua:`Повністю вкрийте овочі оцтовою заправкою й тримайте в холодильнику; пікліз швидкого маринування не призначений для зберігання без охолодження.`,t:[`refrigerator-pickling`],m:180,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`thyme`,3,`sprig`]]}];var d={slug:r,id:t,country:`HT`,region:a,servings:4,minutes:203,title:c,text:g,steps:l};export{n as country,d as default,t as id,o as minutes,a as region,s as servings,r as slug,l as steps,g as text,c as title};